SELECT MIN(users.Age) AS youngest_user_age, MIN(posts.CreaionDate) AS first_post_date
FROM users
INNER JOIN posts ON users.Id = posts.OwnerUserId;

SELECT posts.CreaionDate
FROM posts
INNER JOIN users ON posts.OwnerUserId = users.Id
WHERE users.Age = (
    SELECT MIN(users.Age)
    FROM users
) AND posts.CreaionDate = (
    SELECT MIN(posts.CreaionDate)
    FROM posts
);

SELECT MIN(p.CreaionDate) AS FirstPostCreationDate
FROM posts p
INNER JOIN users u ON p.OwnerUserId = u.Id
WHERE u.Age = (
    SELECT MIN(u2.Age) FROM users u2
);

SELECT p.CreaionDate
FROM posts p
INNER JOIN users u ON p.OwnerUserId = u.Id
WHERE u.Age = (
  SELECT MIN(u2.Age) FROM users u2
) AND p.CreaionDate = (
  SELECT MIN(p3.CreaionDate) FROM posts p3
  WHERE p3.OwnerUserId = (
    SELECT Id FROM users WHERE Age = (
      SELECT MIN(u2.Age) FROM users u2
    )
  ) AND p3.age = u.Age
);

SELECT p.CreaionDate
FROM users u
INNER JOIN posts p ON u.Id = p.OwnerUserId
WHERE u.Age = (
    SELECT MIN(u2.Age) FROM users u2
) AND p.Id = (
    SELECT MIN(p2.PostId) FROM posts p2
);

SELECT p.CreaionDate
FROM users u
INNER JOIN posts p ON u.Id = p.OwnerUserId
WHERE u.Age = (
    SELECT MIN(u2.Age) FROM users u2
) AND p.CreaionDate = (
    SELECT MIN(p2.CreaionDate) FROM posts p2
);

